/*
 *	z88dk RS232 Function — RC700 (Z80-SIO channel A / RDR+PUN)
 *
 *	uint8_t rs232_params(uint8_t params, uint8_t parity)
 *
 *	The SIO-A baud rate is generated by the RC700 firmware's CTC ch0
 *	timer and the frame format is fixed at 8N1 by rs232_init(); the
 *	requested params are accepted but not reprogrammed here.
 */

#include <rs232.h>

uint8_t rs232_params(uint8_t params, uint8_t parity) __smallc
{
    (void)params;
    (void)parity;
    return RS_ERR_OK;
}
